const r = await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd
m=pd.read_csv('/app/dataset/sensor_metadata.csv'); a=pd.read_csv('/app/dataset/alarms.csv');
for _,x in m.iterrows():
 s=x.sensor_id; d=pd.read_csv('/app/dataset/sensors_'+('01' if x.subsystem in ['COOLING','PRIMARY_LOOP'] else '02' if x.subsystem in ['CORE','STEAM_GEN'] else '03')+'.csv'); d=d[d.sensor_id==s].copy(); d['utc']=pd.to_datetime(d.timestamp)-pd.Timedelta(hours=x.logger_utc_offset_hours); d['physical']=d.utc-pd.Timedelta(minutes=x.response_delay_minutes); d['hour']=d.utc.dt.floor('h');
 v=d.value; al=a[a.sensor_id==s];
 hrs=d.groupby('hour').value.mean()
 print(f'{s:20}  mean {v.mean():10.2f} min/max {v.min():10.2f}/{v.max():10.2f} first/last {v.iloc[0]:10.2f}/{v.iloc[-1]:10.2f} alarms {len(al):4} first {al.timestamp.iloc[0] if len(al) else "-":20} {al.value.iloc[0] if len(al) else "-"}  min/max hour {hrs.idxmin().strftime("%m-%d %H:%M")}/{hrs.idxmax().strftime("%m-%d %H:%M")}')
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:4000});text(r.output)

